input.command:
cat > /tmp/setup.sql <<'EOF'
INSTALL spatial; LOAD spatial;
INSTALL httpfs; LOAD httpfs;
SET geometry_always_xy = true;
.timer on
EOF
echo "trying facilities schema..."
timeout 300 duckdb -c "
INSTALL spatial; LOAD spatial; INSTALL httpfs; LOAD httpfs;
DESCRIBE SELECT * FROM read_parquet('https://data.source.coop/tristangruppwri/soft-commodity-infrastructure/facilities/BR_facilities.parquet') LIMIT 1;
"

timeout 600 duckdb -json -c "
INSTALL spatial; LOAD spatial; INSTALL httpfs; LOAD httpfs; SET geometry_always_xy=true;
SELECT 'FAC_COUNT' tag, count(*) n FROM read_parquet('https://data.source.coop/tristangruppwri/soft-commodity-infrastructure/facilities/BR_facilities.parquet');
" 2>&1
echo "=== facilities tiers ==="
timeout 600 duckdb -json -c "
INSTALL spatial; LOAD spatial; INSTALL httpfs; LOAD httpfs; SET geometry_always_xy=true;
SELECT tier, entity_kind, basis, geom_method, count(*) n FROM read_parquet('https://data.source.coop/tristangruppwri/soft-commodity-infrastructure/facilities/BR_facilities.parquet') GROUP BY ALL ORDER BY 1,2,3,4;
" 2>&1

