input.command:
cd /workspace/data
duckdb /workspace/work.db -box -c "
INSTALL spatial; LOAD spatial;
CREATE TABLE listed_in_car AS
SELECT DISTINCT l.cod_imovel FROM listed_ids l
WHERE EXISTS (SELECT 1 FROM read_parquet('car.parquet') c WHERE c.cod_imovel=l.cod_imovel);
SELECT (SELECT count(*) FROM listed_ids) listed,
       (SELECT count(*) FROM listed_in_car) listed_found,
       (SELECT count(*) FROM listed_ids)-(SELECT count(*) FROM listed_in_car) listed_missing;
"

cd /workspace/data
duckdb /workspace/work.db -box -c "
INSTALL spatial; LOAD spatial; SET geometry_always_xy=true;
SELECT min(bbox.xmin) xmin, min(bbox.ymin) ymin, max(bbox.xmax) xmax, max(bbox.ymax) ymax FROM car_parcels;
"
